class Solution {
    public int numDifferentIntegers(String word){
        Set<String> values=new HashSet<>();
        for(int index=0;index<word.length();){
            if(!Character.isDigit(word.charAt(index))){
                index++;
                continue;
            }
            int end=index;
            while(end<word.length()&&Character.isDigit(word.charAt(end)))end++;
            while(index<end&&word.charAt(index)=='0')index++;
            values.add(index==end?"0":word.substring(index,end));
            index=end;
        }
        return values.size();
    }
}

code.kotlin:
class Solution {
    fun numDifferentIntegers(word:String):Int{
        val values=mutableSetOf<String>();
        var position=0;
        while(position<word.length){
            if(!word[position].isDigit()){
                position++;
                continue
            };
            var end=position;
            while(end<word.length&&word[end].isDigit())end++;
            while(position<end&&word[position]=='0')position++;
            values.add(if(position==end)"0" else word.substring(position,end));
            position=end
        };
        return values.size
    }
}

